// credit to https://www.shadertoy.com/view/XslGRr

#ifdef GL_ES
precision mediump float;
#endif

#define LOOK 0
#define NOISE_METHOD 0
#define USE_LOD 0

mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
    vec3 cw = normalize(ta - ro);
    vec3 cp = vec3(sin(cr), cos(cr),0.0);
    vec3 cu = normalize(cross(cw, cp));
    vec3 cv = normalize(cross(cu, cw));
    return mat3(cu, cv, cw);
}

float noise( in vec3 x )
{
    vec3 p = floor(x);
    vec3 f = fract(x);
    f = f*f*(3.0 - 2.0*f);
#if NOISE_METHOD==0
    x = p + f;
    return textureLod(iChannel2,(x+0.5)/32.0,0.0).x*2.0 - 1.0;
#elif NOISE_METHOD==1
    vec2 uv = (p.xy + vec2(37.0,239.0)*p.z) + f.xy;
    vec2 rg = textureLod(iChannel0,(uv+0.5)/256.0,0.0).yx;
    return mix(rg.x, rg.y, f.z)*2.0 - 1.0;
#else
    ivec3 q = ivec3(p);
    ivec2 uv = q.xy + ivec2(37,239)*q.z;
    vec2 rg = mix(
        mix(texelFetch(iChannel0,(uv          )&255,0),
            texelFetch(iChannel0,(uv+ivec2(1,0))&255,0), f.x),
        mix(texelFetch(iChannel0,(uv+ivec2(0,1))&255,0),
            texelFetch(iChannel0,(uv+ivec2(1,1))&255,0), f.x),
        f.y).yx;
    return mix(rg.x, rg.y, f.z)*2.0 - 1.0;
#endif
}

// (LOOK==1) code:
float map(in vec3 p, int oct)
{
    vec3 q = p - vec3(0.0,0.1,1.0)*iTime;
    float g = 0.5 + 0.5*noise(q*0.3);

    float f  = 0.50000*noise(q);     q *= 2.02;
#if USE_LOD==1
    if(oct>=2)
#endif
    f += 0.25000*noise(q);          q *= 2.23;
#if USE_LOD==1
    if(oct>=3)
#endif
    f += 0.12500*noise(q);          q *= 2.41;
#if USE_LOD==1
    if(oct>=4)
#endif
    f += 0.06250*noise(q);          q *= 2.62;
#if USE_LOD==1
    if(oct>=5)
#endif
    f += 0.03125*noise(q);

    f = mix(f*0.1 - 0.5, f, g*g);
    return 1.5*f - 0.5 - p.y;
}

const int kDiv = 1; 
const vec3 sundir = normalize(vec3(1.0,0.0,-1.0));

vec4 raymarch(in vec3 ro, in vec3 rd, in vec3 bgcol, in ivec2 px)
{
    // bounding planes
    float yb = -3.0;
    float yt =  0.6;
    float tb = (yb - ro.y)/rd.y;
    float tt = (yt - ro.y)/rd.y;

    float tmin, tmax;
    // find tightest possible raymarching segment
    if(ro.y>yt)
    {
        // above top plane
        if(tt<0.0) return vec4(0.0);
        tmin = tt;
        tmax = tb;
    }
    else
    {
        // inside cloud slab
        tmin = 0.0;
        tmax = 60.0;
        if(tt>0.0) tmax = min(tmax, tt);
        if(tb>0.0) tmax = min(tmax, tb);
    }

    // dither near distance
    float t = tmin + 0.1 * texelFetch(iChannel1, px & 1023, 0).x;

    vec4 sum = vec4(0.0);
    for(int i=0; i<190*kDiv; i++)
    {
        float dt = max(0.05, 0.02*t/float(kDiv));
        int oct = 5 - int(log2(1.0 + t*0.5));

        vec3 pos = ro + t*rd;
        float den = map(pos, oct);
        if(den>0.01) // if inside
        {
            float dif = clamp((den - map(pos + 0.3*sundir, oct))/0.25,0.0,1.0);
            vec3 lin  = vec3(0.65,0.65,0.75)*1.1 + 0.8*vec3(1.0,0.6,0.3)*dif;
            vec4 col  = vec4(mix(vec3(1.0,0.93,0.84), vec3(0.25,0.3,0.4), den), den);
            col.xyz  *= lin;
            col.xyz   = mix(col.xyz,bgcol,1.0 - exp2(-0.1*t));
            col.w     = min(col.w*8.0*dt,1.0);
            col.rgb  *= col.a;
            sum      += col*(1.0 - sum.a);
        }
        t += dt;
        if(t>tmax || sum.a>0.99) break;
    }
    return clamp(sum,0.0,1.0);
}

vec4 renderClouds(in vec3 ro, in vec3 rd, in ivec2 px)
{
    float sun = clamp(dot(sundir, rd), 0.0, 1.0);

    // background sky
    vec3 col = vec3(0.76,0.75,0.95);
    col -= 0.6 * vec3(0.90,0.75,0.95) * rd.y;
    col += 0.2 * vec3(1.0,0.60,0.10) * pow(sun,8.0);

    // volumetric clouds
    vec4 res = raymarch(ro, rd, col, px);
    col = col*(1.0 - res.w) + res.xyz;

    // sun glare
    col += 0.2*vec3(1.0,0.4,0.2)*pow(sun,3.0);

    // tone-map
    col = smoothstep(0.15,1.1,col);

    return vec4(col,1.0);
}

//-----------------------------------------------------
// LETTER OVERLAY (N → E → O), Shell-Expansion Morph
//-----------------------------------------------------

// Distance from point p to line segment (a->b)
float lineSegDist(vec2 p, vec2 a, vec2 b)
{
    vec2 pa = p - a;
    vec2 ba = b - a;
    float t = clamp(dot(pa, ba)/dot(ba, ba), 0.0, 1.0);
    return length(pa - ba*t);
}

// Stroke SDF for a line
float lineSegSDF(vec2 p, vec2 a, vec2 b, float halfWidth)
{
    return lineSegDist(p, a, b) - halfWidth;
}

// Ring SDF
float ringSDF(vec2 p, float r, float halfTh)
{
    float d = length(p) - r;
    return abs(d) - halfTh;
}

// Smooth union
float opSmoothUnion(float d1, float d2, float k)
{
    float h = clamp(0.5 + 0.5*(d2 - d1)/k,0.0,1.0);
    return mix(d2, d1, h) - k*h*(1.0 - h);
}

// Letters

float letterN(vec2 p)
{
    // Flip Y so N is right-side up
    float dLeft  = lineSegSDF(p, vec2(-0.15, 0.25),  vec2(-0.15, -0.25), 0.02);
    float dRight = lineSegSDF(p, vec2( 0.15, 0.25),  vec2( 0.15, -0.25), 0.02);
    float dDiag  = lineSegSDF(p, vec2(-0.15, 0.25),  vec2( 0.15,-0.25),  0.02);
    return min(dLeft, min(dRight, dDiag));
}

float letterE(vec2 p)
{
    float dVert = lineSegSDF(p, vec2(-0.15, 0.25),  vec2(-0.15, -0.25), 0.02);
    float dTop  = lineSegSDF(p, vec2(-0.15, 0.25),  vec2( 0.15,  0.25), 0.02);
    float dMid  = lineSegSDF(p, vec2(-0.15, 0.00),  vec2( 0.10,  0.00), 0.02);
    float dBot  = lineSegSDF(p, vec2(-0.15,-0.25),  vec2( 0.15, -0.25), 0.02);
    return min(dVert, min(dTop, min(dMid, dBot)));
}

float letterO(vec2 p)
{
    return ringSDF(p, 0.20, 0.02);
}

float letterSDF(vec2 p, int i)
{
    if(i==0) return letterN(p);
    if(i==1) return letterE(p);
    return letterO(p);
}

// "Shell expansion" morph: push A out, B in, then union
float shapeMorph(float dA, float dB, float t)
{
    float fadeOutOffset = 0.5;
    float fadeInOffset  = 0.5;
    float kSmooth       = 0.09;

    float dA_ = dA + t*fadeOutOffset;
    float dB_ = dB + (1.0 - t)*fadeInOffset;
    return opSmoothUnion(dA_, dB_, kSmooth);
}

//-----------------------------------------------------
// MAIN
//-----------------------------------------------------
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //-------------------------------------------------
    // 1) Compute the Cloudy Background
    //-------------------------------------------------

    vec2 p  = fragCoord;
    vec2 res = iResolution.xy;
    vec2 uv = (p - 0.5*res)/res.y;
    vec2 m  = iMouse.xy / res.xy;

    // Camera
    vec3 ro = 4.0 * normalize(vec3(sin(3.0*m.x), 0.8*m.y, cos(3.0*m.x))) 
              - vec3(0.0,0.1,0.0);
    vec3 ta = vec3(0.0, -1.0, 0.0);
    mat3 ca = setCamera(ro, ta, 0.07*cos(0.25*iTime));
    vec3 rd = ca * normalize(vec3(uv, 1.5));

    // Render cloud background
    vec4 cloudCol = renderClouds(ro, rd, ivec2(fragCoord-0.5));

    //-------------------------------------------------
    // 2) Compute the N-E-O Morph
    //-------------------------------------------------

    // We'll do a 12-second cycle for N->E->O->N
    float fullCycle = 12.0;
    float T = mod(iTime, fullCycle);
    // each segment 4 seconds
    int   iCur  = int(floor(T/4.0));    // 0..2
    int   iNext = (iCur + 1)%3;
    float f     = fract(T/4.0);        // [0..1] within segment

    // Cosine easing
    float ease = 0.5*(1.0 - cos(3.14159*f));

    // Our letter coordinate space in [-1..+1]
    vec2 letterUV = (fragCoord - 0.5*res) / res.y;

    // Distances
    float dA = letterSDF(letterUV, iCur);
    float dB = letterSDF(letterUV, iNext);
    float d  = shapeMorph(dA, dB, ease);

    //-------------------------------------------------
    // 3) Modulate Cloud Brightness Using d
    //-------------------------------------------------
    // We want clouds to be BRIGHTER near the letter boundary => "inverse" logic
    // For example:
    //   distFactor ~ 1.0 near |d|=0, and ~0.0 for large |d|.
    // We'll use a smooth range, e.g. 0.0..0.3
    float distFactor = 1.0 - smoothstep(0.0, 0.3, abs(d));
    // distFactor=1.0 if |d|=0 => near letter boundary
    // distFactor=0.0 if |d|>=0.3 => far from letter

    // Let's say we add up to +50% brightness near letter
    // So final cloud multiplier = 1.0 + 0.5 * distFactor
    float brightness = 1.0 + 0.5*distFactor;

    vec3 brightClouds = cloudCol.rgb * brightness;

    //-------------------------------------------------
    // 4) Also Render the White Outline
    //-------------------------------------------------
    // If you still want the white stroke overlay:
    float lineWidth = 0.037; 
    float alpha = 1.0 - smoothstep(lineWidth, lineWidth*3.0, abs(d));
    vec3 letterColor = vec3(1.0); // pure white

    // Combine letter stroke over the brightness-modulated clouds
    vec3 finalColor = mix(brightClouds, letterColor, alpha);

    fragColor = vec4(finalColor, 1.0);
}
